const updateAsset = `-- name: UpdateAsset :one
UPDATE assets SET
    title       = COALESCE($1,       title),
    description = COALESCE($2, description),
    status      = COALESCE($3,      status),
    metadata    = COALESCE($4,    metadata),
    updated_at  = NOW()
WHERE id = $5 AND deleted_at IS NULL
RETURNING id, title, description, asset_type, owner_user_ref, status,
          file_hash, file_extension, file_size_bytes, metadata,
          origin_server_id, state_id, processing_status, thumbhash,
          created_at, updated_at
`

type UpdateAssetParams struct {
	Title       *string
	Description *string
	Status      *string
	Metadata    []byte
	ID          pgtype.UUID
}

type UpdateAssetRow struct {
	ID               pgtype.UUID
	Title            string
	Description      string
	AssetType        int64
	OwnerUserRef     *int64
	Status           string
	FileHash         *string
	FileExtension    *string
	FileSizeBytes    *int64
	Metadata         []byte
	OriginServerID   pgtype.UUID
	StateID          pgtype.UUID
	ProcessingStatus string
	Thumbhash        []byte
	CreatedAt        pgtype.Timestamptz
	UpdatedAt        pgtype.Timestamptz
}

// Partial update via COALESCE: any field passed as NULL keeps its
// current value. Tag changes go through a separate set of queries.
func (q *Queries) UpdateAsset(ctx context.Context, arg UpdateAssetParams) (UpdateAssetRow, error) {
	row := q.db.QueryRow(ctx, updateAsset,
		arg.Title,
		arg.Description,
		arg.Status,
		arg.Metadata,
		arg.ID,
	)
	var i UpdateAssetRow
	err := row.Scan(
		&i.ID,
		&i.Title,
		&i.Description,
		&i.AssetType,
		&i.OwnerUserRef,
		&i.Status,
		&i.FileHash,
		&i.FileExtension,
		&i.FileSizeBytes,
		&i.Metadata,
		&i.OriginServerID,
		&i.StateID,
		&i.ProcessingStatus,
		&i.Thumbhash,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
